# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
#
# GCU400 adaptation (P19 grid limit + Stein budget, 2026-11-18):
# * grid.x hard limit 65535: the KernelGen one-block-per-program grid
#   (cdiv(n, 512)) overflowed on the bench core 2^30-element shapes
#   (Required 2097152 > 65535). Persistent grid-stride with the grid capped
#   at 32768 (clear of the measured 65535 boundary danger zone), same recipe
#   as sgn.py / fake_quantize_per_tensor_affine_cachemask_tensor_qparams.
# * Stein worst case is bits(max(u, v)) - 1, not 2 * bits: each iteration
#   sets u' = min(u, v) and v' = |u - v| >> ctz, so either v' >= u' and the
#   new max is <= |u - v| / 2 < max / 2, or v' < u' and the new max is the
#   old min with at least one bit less. Mersenne pairs (1, 2^b - 1) attain
#   b - 1. MAX_ITERS is therefore the input bit width (8/15/31/63), not the
#   KernelGen 2b (62 even for int16).
# * Wrap semantics measured against CPU aten and native GCU torch.lcm:
#   int8/int16 keep the raw two's-complement wrap of (|x| // g) * |y|,
#   int32/int64 normalize with abs after the wrap.
# * |INT_MIN| = 2^(b-1) only fits the unsigned domain, so abs and the
#   power-of-two strip run on uint, the gcd loop on signed (values < 2^(b-1)
#   after the strip; the single 2^(b-1) case strips down to 1).
# * lcm_ writes in place with one kernel launch on the contiguous
#   same-shape/dtype path instead of out-of-place + copy_.
#
# Measured (do_bench warmup 500ms / rep 100ms median, n = 2^24):
#   int16 10209.5us -> 1147.0us, int32 5861.5us -> 1761.9us
#   (native torch.lcm: 1693.2us / 5842.6us).
import logging

import torch
import triton
import triton.language as tl

from flag_gems.utils import tl_extra_shim

logger = logging.getLogger(__name__)

_GRID_X_CAP = 32768
_BLOCK = 2048
_NUM_WARPS = 4
_I64_BLOCK = 512
_I64_WARPS = 4


@triton.jit
def _ctz_u32(x):
    # libdevice ffs takes a signed argument; only the bit pattern matters.
    return tl_extra_shim.ffs(x.to(tl.int32, bitcast=True)) - 1


@triton.jit
def _ctz_u64(x):
    return tl_extra_shim.ffs(x.to(tl.int64, bitcast=True)) - 1


@triton.jit
def _wrap_abs(x):
    # avoid llvm abs poison on the INT_MIN corner; wrap is well defined
    return tl.where(x < 0, 0 - x, x)


@triton.jit
def lcm_kernel_i32(
    x_ptr,
    y_ptr,
    out_ptr,
    n_elements,
    BLOCK: tl.constexpr,
    MAX_ITERS: tl.constexpr,
    ABS_TAIL: tl.constexpr,
):
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    arange = tl.arange(0, BLOCK)
    num_blocks = (n_elements + BLOCK - 1) // BLOCK
    for block_id in tl.range(pid, num_blocks, num_pids):
        offsets = block_id * BLOCK + arange
        mask = offsets < n_elements

        x = tl.load(x_ptr + offsets, mask=mask, other=0)
        y = tl.load(y_ptr + offsets, mask=mask, other=0)

        xu = x.to(tl.uint32)
        yu = y.to(tl.uint32)
        ax_u = tl.where(x < 0, 0 - xu, xu)
        ay_u = tl.where(y < 0, 0 - yu, yu)
        common = _ctz_u32(ax_u | ay_u)
        zx = tl.where(ax_u == 0, 1, ax_u)
        zy = tl.where(ay_u == 0, 1, ay_u)
        u = (zx >> _ctz_u32(zx)).to(tl.int32)
        v = (zy >> _ctz_u32(zy)).to(tl.int32)
        both_nonzero = (x != 0) & (y != 0)

        # min/max Stein; converged state is u == v and the body is
        # idempotent there, so the fixed budget never corrupts a result.
        for _ in tl.static_range(MAX_ITERS):
            d = u - v
            nu = tl.minimum(u, v)
            nv = tl.abs(d)
            nv = tl.where(nv == 0, nu, nv >> _ctz_u32(tl.where(nv == 0, 1, nv)))
            u = nu
            v = nv

        gcd_u = tl.where(both_nonzero, u.to(tl.uint32) << common, 0)
        gsafe = tl.where(gcd_u == 0, 1, gcd_u)
        prod = (ax_u // gsafe) * ay_u
        prod = tl.where(both_nonzero, prod, 0)
        result = prod.to(tl.int32)
        if ABS_TAIL:
            result = _wrap_abs(result)
        tl.store(out_ptr + offsets, result.to(out_ptr.type.element_ty), mask=mask)


@triton.jit
def lcm_kernel_i64(
    x_ptr,
    y_ptr,
    out_ptr,
    n_elements,
    BLOCK: tl.constexpr,
    MAX_ITERS: tl.constexpr,
    ABS_TAIL: tl.constexpr,
):
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    arange = tl.arange(0, BLOCK)
    num_blocks = (n_elements + BLOCK - 1) // BLOCK
    for block_id in tl.range(pid, num_blocks, num_pids):
        offsets = block_id * BLOCK + arange
        mask = offsets < n_elements

        x = tl.load(x_ptr + offsets, mask=mask, other=0)
        y = tl.load(y_ptr + offsets, mask=mask, other=0)

        xu = x.to(tl.uint64)
        yu = y.to(tl.uint64)
        ax_u = tl.where(x < 0, 0 - xu, xu)
        ay_u = tl.where(y < 0, 0 - yu, yu)
        common = _ctz_u64(ax_u | ay_u)
        zx = tl.where(ax_u == 0, 1, ax_u)
        zy = tl.where(ay_u == 0, 1, ay_u)
        u = (zx >> _ctz_u64(zx)).to(tl.int64)
        v = (zy >> _ctz_u64(zy)).to(tl.int64)
        both_nonzero = (x != 0) & (y != 0)

        for _ in tl.static_range(MAX_ITERS):
            d = u - v
            nu = tl.minimum(u, v)
            nv = tl.abs(d)
            nv = tl.where(nv == 0, nu, nv >> _ctz_u64(tl.where(nv == 0, 1, nv)))
            u = nu
            v = nv

        gcd_u = tl.where(both_nonzero, u.to(tl.uint64) << common, 0)
        gsafe = tl.where(gcd_u == 0, 1, gcd_u)
        prod = (ax_u // gsafe) * ay_u
        prod = tl.where(both_nonzero, prod, 0)
        result = prod.to(tl.int64)
        if ABS_TAIL:
            result = _wrap_abs(result)
        tl.store(out_ptr + offsets, result.to(out_ptr.type.element_ty), mask=mask)


def _launch(lhs, rhs, out, numel, dtype):
    if dtype == torch.int64:
        grid = (min(triton.cdiv(numel, _I64_BLOCK), _GRID_X_CAP),)
        lcm_kernel_i64[grid](
            lhs,
            rhs,
            out,
            numel,
            BLOCK=_I64_BLOCK,
            MAX_ITERS=63,
            ABS_TAIL=True,
            num_warps=_I64_WARPS,
        )
        return
    if dtype == torch.int32:
        max_iters, abs_tail = 31, True
    elif dtype == torch.int16:
        max_iters, abs_tail = 15, False
    elif dtype in (torch.int8, torch.uint8):
        max_iters, abs_tail = 8, False
    else:
        raise TypeError(f"unsupported dtype for lcm: {dtype}")
    grid = (min(triton.cdiv(numel, _BLOCK), _GRID_X_CAP),)
    lcm_kernel_i32[grid](
        lhs,
        rhs,
        out,
        numel,
        BLOCK=_BLOCK,
        MAX_ITERS=max_iters,
        ABS_TAIL=abs_tail,
        num_warps=_NUM_WARPS,
    )


def _materialize_inputs(self, other):
    if (
        self.dtype == other.dtype
        and self.shape == other.shape
        and self.is_contiguous()
        and other.is_contiguous()
    ):
        return self, other, self.dtype
    promoted_dtype = torch.promote_types(self.dtype, other.dtype)
    lhs = self if self.dtype == promoted_dtype else self.to(promoted_dtype)
    rhs = other if other.dtype == promoted_dtype else other.to(promoted_dtype)
    lhs, rhs = torch.broadcast_tensors(lhs, rhs)
    return lhs.contiguous(), rhs.contiguous(), promoted_dtype


def lcm(self, other):
    """Compute element-wise least common multiple.

    Uses binary GCD (Stein's algorithm) for efficiency, then derives
    lcm(a, b) = |a| / gcd(a, b) * |b| to avoid intermediate overflow.
    """
    logger.debug("GEMS_ENFLAME LCM")
    lhs, rhs, promoted_dtype = _materialize_inputs(self, other)
    result = torch.empty_like(lhs, dtype=promoted_dtype)
    numel = result.numel()
    if numel == 0:
        return result

    _launch(lhs.reshape(-1), rhs.reshape(-1), result.reshape(-1), numel, promoted_dtype)
    return result.view(lhs.shape)


def lcm_(self, other):
    """In-place version of lcm."""
    logger.debug("GEMS_ENFLAME LCM_")
    numel = self.numel()
    if (
        numel > 0
        and self.dtype == other.dtype
        and self.shape == other.shape
        and self.is_contiguous()
        and other.is_contiguous()
    ):
        flat = self.reshape(-1)
        _launch(flat, other.reshape(-1), flat, numel, self.dtype)
        return self
    result = lcm(self, other)
    self.copy_(result)
    return self
